function cacheKey(f,page){return f.id+':'+page;}
function clearOCRPanel(){$('ocrResult').hidden=true;$('ocrProgress').hidden=true;$('ocrStatus').textContent='';$('ocrSuggestions').replaceChildren();}
function showCachedOCR(f,page){const result=state.ocrCache.get(cacheKey(f,page));if(!result)return;$('ocrResult').hidden=false;$('ocrText').value=result.corrected??result.text;$('ocrStatus').textContent='Texto reconocido de la página '+page+'. Revisa nombres, cifras y fechas.';showSuggestions($('ocrText').value);}
