  if(state.renderTask){try{await state.renderTask.promise;}catch{}}
  const page=await f.view.getPage(pageNumber),base=page.getViewport({scale:1});const scale=Math.min(2.5,1800/base.width,Math.sqrt(3500000/(base.width*base.height)));const viewport=page.getViewport({scale});canvas=document.createElement('canvas');canvas.width=Math.floor(viewport.width);canvas.height=Math.floor(viewport.height);
  await page.render({canvasContext:canvas.getContext('2d'),viewport,background:'rgb(255,255,255)'}).promise;
