  state.ocrCache.set(cacheKey(f,pageNumber),{text:result.text||'',confidence:Number(result.confidence)||0});showCachedOCR(f,pageNumber);if(!result.text?.trim())$('ocrStatus').textContent='No se reconoció texto legible. Revisa la calidad y orientación del escaneo.';say('OCR terminado para la página '+pageNumber+'. Verifica el texto frente a la imagen.');
